    '  background: var(--bw-nav-glass) !important;',
    '  -webkit-backdrop-filter: blur(22px) !important;',
    '  backdrop-filter: blur(22px) !important;',
    '  border: 0 !important;',
    '  outline: 1px solid var(--bw-chip-line) !important;',
    '  outline-offset: -1px !important;',
