    '#app .prf-handle .prf-num b { color: #7A8499 !important; font-weight: 400 !important; }',
    '/* 三态按钮统一到品牌蓝:关注(渐变实心)/ 已关注·编辑资料(浅蓝描边)/ 私信(同色系胶囊) */',
    '#app .profile-header .m-btn-blue {',
    '  background: linear-gradient(135deg, #5B8DEF, #2563EB) !important;',
    '  color: #FFFFFF !important;',
    '  border: 0 !important;',
    '  box-shadow: 0 4px 12px rgba(37,99,235,.28) !important;',
    '}',
    '#app .profile-header .m-btn-lite-white {',
    '  background: #F5F8FF !important;',
    '  color: #2563EB !important;',
    '  border: 1px solid rgba(37,99,235,.26) !important;',
    '}',
    '/* 站点用伪元素画的灰色发丝边框会和新描边叠成两层,去掉',
    '   (只针对描边态按钮,关注按钮的 .m-add-box::before 是"+"号,不能动) */',
