    '  border: 0 !important;',
    '  box-shadow: inset 0 0 0 1px var(--bw-line) !important;',
    '}',
    '/* 站点自己的浮动"编辑资料"蓝球与卡里的按钮重复,隐藏 */',
    '#app .icon_edit { display: none !important; }',
    '/* 列表尾部的"查看全部微博" */',
    '#app .lite-btn-more {',
