    '/* 输入框:下划线式改成填充式,聚焦才提亮 + 描一圈焦点环(状态要看得见) */',
    'div.bg-card form { margin-top: 22px !important; }',
    'div.bg-card div.relative.mt-2\\.5 { margin-top: 10px !important; }',
